# One-time small public index, excluding bin/obj and all private data.
$ErrorActionPreference='Stop';$workspace=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$evidence=Join-Path $workspace 'evidence/det-001'
$validation='evidence/det-001/validation-final-v3/receipt.json';$receipt=Get-Content -LiteralPath (Join-Path $workspace $validation) -Raw|ConvertFrom-Json
if($receipt.Status -cne 'READY_FIRST_RESHUFFLE_CONTRACT' -or $receipt.Runtime -cne 'HOLD' -or $receipt.FormalAttempts -ne 0 -or $receipt.LegacyDeliveryTargetsVerified -ne 158){throw 'NOT_READY'}
$own=@(Get-ChildItem -LiteralPath $PSScriptRoot -File|Where-Object Extension -in @('.cs','.csproj','.ps1'))
$public=@(Get-ChildItem -LiteralPath $evidence -File -Recurse|Where-Object Name -CNE 'phase0-delivery-2026-10-23.json')
$report=Join-Path $workspace 'project-management/investigation-reports/DET-001-Phase0-report.md';$targets=@($own.FullName)+@($public.FullName)+@($report)
$files=@(foreach($path in @($targets|Sort-Object -Unique)){$absolute=[IO.Path]::GetFullPath($path);if(-not $absolute.StartsWith($workspace+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'FILE_SCOPE'};for($part=$absolute;$part;$part=[IO.Path]::GetDirectoryName($part)){if(Test-Path -LiteralPath $part){if(((Get-Item -LiteralPath $part).Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0){throw 'REPARSE_PATH'}}};$info=Get-Item -LiteralPath $absolute;@{Path=[IO.Path]::GetRelativePath($workspace,$absolute).Replace('\','/');Bytes=$info.Length;SHA256=(Get-FileHash -LiteralPath $absolute).Hash}})
$sourceReceipt=Get-Content -LiteralPath (Join-Path $evidence 'validation-final-v3/cases/receipt.json') -Raw|ConvertFrom-Json
$inputs=@(foreach($entry in $sourceReceipt.Inputs){$path=Join-Path $workspace $entry.Path;@{Path=$entry.Path;Bytes=(Get-Item -LiteralPath $path).Length;SHA256=$entry.SHA256}})
$oldIndex='evidence/spike-001b/runtime-delivery-2026-10-23.json';$oldIndexHash=(Get-FileHash -LiteralPath (Join-Path $workspace $oldIndex)).Hash
if($oldIndexHash -cne '1605625D8DB968423EE5455B20A956EDD801023BF24378DA5B71F2E8A037BF9C'){throw 'OLD_INDEX_IDENTITY'}
$index=[ordered]@{Schema=1;Date='2026-10-23';Timezone='Asia/Shanghai';Task='DET-001 Phase0';Result='READY_FIRST_RESHUFFLE_CONTRACT';Runtime='HOLD';FormalAttempts=0;ActualReshuffleObserved=$false;RuntimeModDllOrManifestImplemented=$false;PreferredPath='Plain ten-card Ironclad Act1 weak Monster; first natural reshuffle at Round3 under explicit eligibility';ExpectedFirstReshuffleRound=3;MaxEndTurns=2;MaxAcceptedOperations=4;StablePoints=5;RngOwnerStream='player.RunState.Rng.Shuffle';ExpectedTargetCounterAndKernelSteps=9;RngAlreadyCoveredBy001BProjection=$true;Validation=$validation;ComparisonCases=11;SyntheticFlowCases=15;Report='project-management/investigation-reports/DET-001-Phase0-report.md';Reproduction='experiments/DET-001/Invoke-OfflineValidation.ps1';ReadOnlyVerification='experiments/DET-001/Verify-Phase0Delivery.ps1';FixedGameAssembly=@{Bytes=9757184;SHA256='0861BFA1DF347538D932F22D580E75420F08082792EB914E53B4882764ACDBE9';Version='v0.111.0';Commit='41cef1ea'};ApprovedComparator=@{Path='experiments/SPIKE-001B-r2/artifacts-phase0-r2/SPIKE001B.dll';Bytes=200192;SHA256=$receipt.ComparatorDependencySHA256};LegacyIndex=$oldIndex;LegacyIndexSHA256=$oldIndexHash;LegacyPublicTargetsVerified=158;DevelopmentOutputsRetained='validation-v1 / validation-final-v1 / validation-final-v2; final-v3 alone binds final tested sources';CurrentAccountPrivateLogProfileRecoveryRead=$false;SettingsEnabledLiveModsWritten=$false;GameStartedOrRequested=$false;OldProbeRebuiltOrChanged=$false;Inputs=$inputs;Files=$files}
$dest=Join-Path $evidence 'phase0-delivery-2026-10-23.json';$bytes=[Text.Encoding]::UTF8.GetBytes(($index|ConvertTo-Json -Depth 10)+[Environment]::NewLine);$s=[IO.File]::Open($dest,[IO.FileMode]::CreateNew);try{$s.Write($bytes);$s.Flush($true)}finally{$s.Dispose()}
& (Join-Path $PSScriptRoot 'Verify-Phase0Delivery.ps1')
foreach($path in $targets+@($dest)){$item=Get-Item -LiteralPath $path;$item.Attributes=$item.Attributes -bor [IO.FileAttributes]::ReadOnly}
"SEALED DET001 Phase0 files=$($files.Count); indexSHA256=$((Get-FileHash -LiteralPath $dest).Hash)"
